	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4799,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4799:
	.ascii	"sh:disjoint"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4799, 11

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4800,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4800,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4800:
	.ascii	"A SHACL sh:disjoint constraint keeps the values apart from the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4800, 287

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4801,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4801,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4801:
	.ascii	"sh:equals"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4801, 9

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4802,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4802,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4802:
	.ascii	"A SHACL sh:equals constraint requires the values to be exactly the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4802, 291

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4803,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4803,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4803:
