	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4803, 13

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4804,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4804,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4804:
