.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4805:
	.ascii	"sh:lessThan"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4805, 11

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4806,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4806,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4806:
	.ascii	"A SHACL sh:lessThan constraint orders the values below every node a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4806, 284

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4807,@object
