.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4855:
	.ascii	"sh:qualifiedValueShape"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4855, 22

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4856,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4856,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4856:
	.ascii	"A sh:qualifiedValueShape constraint counts the value nodes that conform to a shape, which the value schema cannot judge from a node reference; on a node shape, where it is not well-formed, it judges the focus node itself, which an object schema describing the node's properties does not state, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4856, 323

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4857,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4857,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4857:
	.ascii	"sh:closed"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4857, 9

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4858,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4858,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4858:
	.ascii	"A sh:closed true constraint on a property shape limits the properties of each value node, which its node reference does not carry, so the constraint is dropped (on a node shape it is projected as additionalProperties false)."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4858, 224

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4859,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4859,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4859:
	.ascii	"sh:uniqueLang"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4859, 13

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4860,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4860,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4860:
	.ascii	"A sh:uniqueLang true constraint forbids two values sharing a language tag, which a schema constraining each value alone cannot state; on a node shape, where it is not well-formed, it judges the focus node itself, which an object schema describing the node's properties does not state, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4860, 314

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4861,@object
