.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4861:
	.ascii	"sh:ConstraintComponent"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4861, 22

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4862,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4862,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4862:
	.ascii	"A custom SPARQL-based constraint component (named in the note) validates through a SPARQL query, which has no closed-world JSON Schema equivalent, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4862, 176

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4863,@object
