	.ascii	"sh:minCount"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4863, 11

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4864,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4864,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4864:
	.ascii	"A sh:minCount constraint on a node shape or a member shape, where it is not well-formed, judges the focus node itself rather than a property's values, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4864, 180

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4865,@object
