	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4877, 7

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4878,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4878,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4878:
	.ascii	"A property shape whose path is not one predicate (an inverse, sequence, alternative or closure path) constrains no outgoing JSON property of the projected node, so the property shape is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4878, 194

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4879,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4879,"a",@progbits
