	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4884,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4884:
	.ascii	"A SHACL 1.2 sh:reificationRequired true constraint requires each value's triple to be reified, which the projected value does not state, so the constraint is dropped."
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.4884, 166

