	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5983,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5983,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5983:
	.ascii	"malformed pattern: unterminated character class (missing closing ']')"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5983, 69

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5984,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5984,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5984:
	.ascii	"malformed pattern: unescaped '[' inside a character class -- XML Schema Part 2 Appendix G's charGroup defines no nested character class there, so regex-syntax's nested-class union is a different language; a literal '[' must be escaped as '\\['"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5984, 242

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5985,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5985,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5985:
	.ascii	"malformed pattern: unescaped ']' outside a character class -- it only ever closes a character class in the XSD/XPath grammar, and a literal one must be escaped as '\\]'"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5985, 167

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5986,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5986,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5986:
	.ascii	"malformed pattern: literal ']' at the head of a character class -- XSD's charGroup requires at least one member, and a literal ']' must be escaped as '\\]'"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5986, 154

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5987,@object
	.section	.rodata.str1.1,"aMS",@progbits,1
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5987:
	.asciz	"\023malformed pattern: \300\2002\001 follows a character-class subtraction operand -- XML Schema Part 2 Appendix G's charGroup ::= (posCharGroup | negCharGroup) ('-' charClassExpr)? makes the subtraction the LAST element of the group, so only the enclosing ']' may follow it; there is at most one subtraction per group and no trailing members"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5987, 331

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5988,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5988,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5988:
	.asciz	"\023malformed pattern: \300\200\360\000 is not a construct of the XSD/XPath regular-expression grammar (XML Schema Part 2 Appendix G defines no inline-flag, lookaround, comment, or named-group syntax); the only `(?` group spelling the grammar has is the non-capturing group `(?:`"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5988, 265

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5989,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5989,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5989:
	.ascii	"malformed pattern: \\0 is not a construct of the XSD/XPath regular-expression grammar (a back-reference starts at \\1, and \\0 is not a single-character escape)"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5989, 157

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5990,@object
	.section	.rodata..Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5990,"a",@progbits
.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5990:
	.asciz	"\024malformed pattern: \\\300\200\313\000 is not a construct of the XSD/XPath regular-expression grammar -- XML Schema Part 2 Appendix G enumerates its single-character escapes exactly (\\n \\r \\t \\\\ \\| \\. \\? \\* \\+ \\( \\) \\{ \\} \\- \\[ \\] \\^), and \\\310\000\000\022 is not among them"
	.size	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5990, 251

	.type	.Lanon.447fff4b9dda9460ad50c7a2ae3359e8.5991,@object
